CustomCSS:
/* straight brainrot — wallpaper on body (XP / Rainforest pattern), UI above it */

:root {
  --vro-bg-url: url("https://betterseqta.org/api/background.webp");
  --vro-glass: rgba(12, 12, 18, 0.72);
  --vro-glass-soft: rgba(12, 12, 18, 0.55);
  --vro-border: rgba(255, 255, 255, 0.14);
}

html {
  min-height: 100% !important;
  background-color: #0a0a10 !important;
}

html.dark {
  --background-primary: rgba(18, 18, 26, 0.88);
  --background-secondary: rgba(28, 28, 38, 0.9);
  --theme-primary: rgba(18, 18, 26, 0.88);
  --theme-secondary: rgba(28, 28, 38, 0.9);
  --text-primary: #f4f4f8;
  --text-color: #f4f4f8;
}

html:not(.dark) {
  --background-primary: rgba(255, 255, 255, 0.88);
  --background-secondary: rgba(245, 245, 250, 0.9);
  --theme-primary: rgba(255, 255, 255, 0.88);
  --theme-secondary: rgba(245, 245, 250, 0.9);
  --text-primary: #1a1a22;
  --text-color: #1a1a22;
}

/* Blurred bleed in letterbox gaps (behind sharp body background) */
body::before {
  content: "";
  position: fixed;
  inset: -15%;
  z-index: -1;
  pointer-events: none;
  background-image: var(--vro-bg-url, var(--vro-bg-fallback));
  background-size: cover;
  background-position: center;
  filter: blur(48px) saturate(1.25);
  transform: scale(1.1);
}

/* Sharp centred wallpaper — inset on pseudo only (no body padding on SEQTA UI) */
body::after {
  content: "";
  position: fixed;
  inset: clamp(12px, 3vw, 48px);
  z-index: -1;
  pointer-events: none;
  background-image: var(--vro-bg-url, var(--vro-bg-fallback));
  background-repeat: no-repeat;
  background-position: center center;
  background-size: contain;
}

html.dark body,
html:not(.dark) body {
  background-color: transparent !important;
  background-image: none !important;
}

@media (max-width: 900px) {
  body::after {
    inset: clamp(8px, 2vw, 24px);
  }
}


#container {
  background: unset !important;
}

#container > .bg {
  background: transparent !important;
  opacity: 0 !important;
  pointer-events: none !important;
}

#content {
  background: transparent !important;
}

#title {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 71px !important;
  min-height: 71px !important;
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  box-sizing: border-box !important;
  padding-right: 56px !important;
  z-index: 20 !important;
  background: var(--vro-glass) !important;
  color: var(--text-primary) !important;
  border-bottom: 1px solid var(--vro-border) !important;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35) !important;
  backdrop-filter: blur(20px) saturate(1.2);
}

#title * {
  color: var(--text-primary) !important;
}

.titlebar {
  background: transparent !important;
  z-index: 21 !important;
}

.connectedNotificationsWrapper {
  z-index: 21 !important;
}

#LightDarkModeButton,
#AddedSettings {
  z-index: 22 !important;
}

#menu {
  background: var(--vro-glass) !important;
  color: var(--text-primary) !important;
  border-right: 1px solid var(--vro-border) !important;
  box-shadow: 8px 0 32px rgba(0, 0, 0, 0.28) !important;
  backdrop-filter: blur(22px) saturate(1.15);
}

#menu * {
  color: var(--text-primary) !important;
}

#menu li:hover,
#menu section:hover {
  background: color-mix(in srgb, var(--better-main) 18%, transparent) !important;
}

#menu li.active,
#menu section.active {
  background: color-mix(in srgb, var(--better-main) 28%, transparent) !important;
  box-shadow: inset 4px 0 0 var(--better-main);
}

#main {
  background: transparent !important;
  color: var(--text-primary) !important;
}

#main > .dashboard section,
.dashlet,
.notice,
.document,
.dashboard > div,
.dashboard > .message,
.timetable-container,
.notices-container,
.shortcut-container > .border,
#home-container > div {
  background: var(--vro-glass) !important;
  color: var(--text-primary) !important;
  border: 1px solid var(--vro-border) !important;
  border-radius: 14px !important;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.32) !important;
  backdrop-filter: blur(18px) saturate(1.1);
}

#main > .dashboard section *,
.dashlet *,
.notice *,
.document * {
  color: var(--text-primary) !important;
}

.shortcut {
  background: var(--vro-glass-soft) !important;
  border: 1px solid var(--vro-border) !important;
  border-radius: 12px !important;
  backdrop-filter: blur(14px);
}

.day,
.quickbar {
  background: var(--vro-glass) !important;
  border: 1px solid var(--vro-border) !important;
  border-radius: 12px !important;
  backdrop-filter: blur(16px);
}

.uiButton,
.addedButton,
[class*="uiButton"] {
  background: var(--vro-glass-soft) !important;
  border: 1px solid var(--vro-border) !important;
  border-radius: 10px !important;
  color: var(--text-primary) !important;
  backdrop-filter: blur(12px);
}

.addedButton svg,
.addedButton svg path,
.addedButton svg g,
#LightDarkModeButton svg,
#LightDarkModeButton svg path,
#AddedSettings svg,
#AddedSettings svg path {
  fill: var(--text-primary) !important;
  color: var(--text-primary) !important;
}

input,
select,
textarea {
  background: color-mix(in srgb, var(--background-primary) 92%, transparent) !important;
  border: 1px solid var(--vro-border) !important;
  color: var(--text-primary) !important;
  border-radius: 10px !important;
}

a {
  color: color-mix(in srgb, var(--better-main) 85%, white) !important;
}

html.dark a {
  color: color-mix(in srgb, var(--better-main) 90%, white) !important;
}

[class*="MessageList__MessageList___"],
[class*="BasicPanel__BasicPanel___"] {
  background: var(--vro-glass) !important;
  border: 1px solid var(--vro-border) !important;
  border-radius: 14px !important;
  backdrop-filter: blur(16px);
}
